CREATE TABLE `velix_derivatives` (`id` text PRIMARY KEY NOT NULL, `parent_run_id` text NOT NULL REFERENCES `velix_production_runs`(`id`) ON DELETE CASCADE, `child_run_id` text REFERENCES `velix_production_runs`(`id`) ON DELETE SET NULL, `storyboard_version` integer NOT NULL, `format_id` text NOT NULL, `scene_ids` text NOT NULL, `start_ms` integer NOT NULL, `end_ms` integer NOT NULL, `title` text NOT NULL, `score` real NOT NULL, `reason` text NOT NULL, `claim_ids` text NOT NULL DEFAULT '[]', `status` text NOT NULL DEFAULT 'candidate', `created_at` text NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')), `updated_at` text NOT NULL DEFAULT (datetime('now')))